use super::*;
use semio_framework_value_ordered::{OrderedMap,BorrowedLookupCursor};
use semio_framework_value_testing_allocator::observe_retirement_allocations;
use semio_framework_value_testing_effect_bank::{EffectBank,Wallet};
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn denied(d:RetirementDemand,g:RetainedCloneGrant)->impl Iterator<Item=RetainedCloneGrant>{[(true,RetainedCloneGrant{maximum_items:0,..g}),(d.copy_bytes>0,RetainedCloneGrant{maximum_copy_bytes:d.copy_bytes.saturating_sub(1),..g}),(d.capacity_bytes>0,RetainedCloneGrant{maximum_capacity_bytes:d.capacity_bytes.saturating_sub(1),..g}),(d.release_bytes>0,RetainedCloneGrant{maximum_release_bytes:d.release_bytes.saturating_sub(1),..g}),(d.depth>0,RetainedCloneGrant{maximum_depth:d.depth.saturating_sub(1),..g})].into_iter().filter_map(|(active,g)|active.then_some(g))}
fn model()->serde_json::Value{let model:serde_json::Value=serde_json::from_str(include_str!("native.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("native.schema.json")).unwrap();for(key,value)in model.as_object().unwrap(){assert_eq!(&schema["properties"][key]["const"],value)}model}
fn bank(model:&serde_json::Value)->EffectBank{let stock=&model["stock"];EffectBank::new(Wallet::new(RetainedCloneGrant{maximum_items:stock["items"].as_u64().unwrap()as usize,maximum_copy_bytes:stock["copyBytes"].as_u64().unwrap()as usize,maximum_capacity_bytes:stock["capacityBytes"].as_u64().unwrap()as usize,maximum_release_bytes:stock["releaseBytes"].as_u64().unwrap()as usize,maximum_depth:stock["depth"].as_u64().unwrap()as usize},stock["work"].as_u64().unwrap()))}
fn turn(bank:&mut EffectBank,g:RetainedCloneGrant,work:u64,run:impl FnOnce(&mut RetainedAllocationEffect<'_>)->RetainedWorkOutcome<RetainedCloneStep>)->RetainedWorkOutcome<RetainedCloneStep>{
 let mut run=Some(run);let((poll,marker),heap)=observe_retirement_allocations(||bank.run(g,work,|effect|semio_framework_value_control_contract::RetainedWorkPoll::Complete(run.take().unwrap()(effect))));let semio_framework_value_control_contract::RetainedWorkPoll::Complete(turn)=poll else{panic!("closed native lookup stayed pending")};assert_eq!(marker,None);assert_eq!(heap,(0,0));let p=turn.result.as_ref().map_or_else(ValueError::retained_progress,|step|step.progress());assert!(p.fits(g));assert_eq!(bank.take_admitted(),if turn.work==0{None}else{Some(true)});bank.post(p,g,heap);turn
}
fn close_input(map:OrderedMap<usize>){use semio_framework_value_ordered::ordered::RetirementStep;let mut owner=map.retire();for _ in 0..10000{if owner.is_empty(){return}let g=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:4096,maximum_release_bytes:owner.next_close_byte_demand().unwrap(),maximum_depth:owner.next_depth_demand(),..Default::default()};match owner.advance(g){RetirementStep::Failure(error)=>panic!("cold lookup input refusal: {error}"),_=>{}}}panic!("cold lookup input teardown stalled")}
fn close<V>(cursor:&mut Option<BorrowedLookupCursor<'_,'_,V>>,bank:&mut EffectBank,model:&serde_json::Value){
 let d=BorrowedLookupCursor::close_demand(cursor);assert_eq!(d.copy_bytes,model["closeCopy"].as_u64().unwrap()as usize);let g=grant(d);for denied in denied(d,g){let result=turn(bank,denied,1,|effect|BorrowedLookupCursor::close_from(cursor,effect));assert_eq!(result.work,0);assert_eq!(result.result.unwrap().progress(),Default::default());assert!(cursor.is_some())}let result=turn(bank,g,1,|effect|BorrowedLookupCursor::close_from(cursor,effect));assert_eq!(result.work,1);assert_eq!(result.result.unwrap().progress().copied_bytes,d.copy_bytes);assert!(cursor.is_none())
}
#[test]
fn original_borrowed_lookup_matches_cold_map_and_sql_goldens_with_exact_receipts(){
 let model=model();let corpus:serde_json::Value=serde_json::from_str(include_str!("../../../🧪️tests/🧫️fixtures/🔣️ordered-map.json")).unwrap();let cases=&corpus["borrowedLookupCases"];let body=model["body"].as_u64().unwrap()as usize;
 for case in cases.as_array().unwrap(){for cut in [None,Some(0),Some(1),Some(3),Some(5),Some(15)]{
  let entries:Vec<(String,usize)>=serde_json::from_value(case["entries"].clone()).unwrap();let map:OrderedMap<usize>=entries.into_iter().collect();let query=case["query"].as_str().unwrap().to_owned();let pointer=query.as_ptr();let expected:Option<usize>=serde_json::from_value(case["expected"].clone()).unwrap();assert_eq!(map.get(&query).copied(),expected);let mut bank=bank(&model);let mut cursor=None;
  let d=map.lookup_borrowed_constructor_demands();assert_eq!(d.copy_bytes,model["constructorCopy"].as_u64().unwrap()as usize);let g=grant(d);for denied in denied(d,g){let result=turn(&mut bank,denied,1,|effect|map.admit_lookup_borrowed_into(&query,&mut cursor,effect));assert_eq!(result.work,0);assert_eq!(result.result.unwrap().progress(),Default::default());assert!(cursor.is_none())}let result=turn(&mut bank,g,0,|effect|map.admit_lookup_borrowed_into(&query,&mut cursor,effect));assert_eq!(result.work,0);assert!(cursor.is_none());let result=turn(&mut bank,g,1,|effect|map.admit_lookup_borrowed_into(&query,&mut cursor,effect));assert_eq!(result.work,1);assert_eq!(result.result.unwrap().progress().copied_bytes,d.copy_bytes);let mut complete=false;
  for index in 0..10000{
   if cut==Some(index){break}let d=cursor.as_ref().unwrap().next_demands(&query,body).unwrap();let work=cursor.as_ref().unwrap().next_work_demand(&query,body).unwrap();assert!(work<=model["maximumTurnWork"].as_u64().unwrap());let g=grant(d);
   for denied in denied(d,g){let result=turn(&mut bank,denied,work,|effect|cursor.as_mut().unwrap().advance_into(&query,body,effect));assert_eq!(result.work,0);assert_eq!(result.result.unwrap().progress(),Default::default());assert_eq!(cursor.as_ref().unwrap().next_demands(&query,body).unwrap(),d)}
   if work!=0{let result=turn(&mut bank,g,work-1,|effect|cursor.as_mut().unwrap().advance_into(&query,body,effect));assert_eq!(result.work,0);assert_eq!(result.result.unwrap().progress(),Default::default());assert_eq!(cursor.as_ref().unwrap().next_demands(&query,body).unwrap(),d)}
   let result=turn(&mut bank,g,work,|effect|cursor.as_mut().unwrap().advance_into(&query,body,effect));let step=result.result.unwrap();assert!(result.work<=u128::from(work));assert!(cursor.as_ref().unwrap().last_compared_bytes()<=body);assert_eq!(step.progress().retained_capacity_bytes,0);if cursor.as_ref().unwrap().is_complete(){complete=true;break}
  }
  if cut.is_none(){assert!(complete);assert_eq!(cursor.as_ref().unwrap().result().copied(),expected);assert_eq!(serde_json::to_value(cursor.as_ref().unwrap().result_rank()).unwrap(),case["expectedRank"])}close(&mut cursor,&mut bank,&model);drop(cursor);assert_eq!(query.as_ptr(),pointer);assert_eq!(map.get(&query).copied(),expected);close_input(map);
 }}
}
#[test]
fn original_borrowed_lookup_refuses_a_replaced_query_and_owned_only_entry(){
 let model=model();let map:OrderedMap<usize>=[("needle".to_owned(),7)].into();let query="needle".to_owned();let replaced=query.clone();let mut bank=bank(&model);let mut cursor=None;let g=grant(map.lookup_borrowed_constructor_demands());turn(&mut bank,g,1,|effect|map.admit_lookup_borrowed_into(&query,&mut cursor,effect)).result.unwrap();assert_ne!(query.as_ptr(),replaced.as_ptr());let body=model["body"].as_u64().unwrap()as usize;let d=cursor.as_ref().unwrap().next_demands(&query,body).unwrap();let g=grant(d);assert!(cursor.as_ref().unwrap().next_demands(&replaced,body).is_err());let result=turn(&mut bank,g,model["maximumTurnWork"].as_u64().unwrap(),|effect|cursor.as_mut().unwrap().advance_into(&replaced,body,effect));assert_eq!(result.work,0);assert!(result.result.is_err());assert_eq!(cursor.as_ref().unwrap().next_demands(&query,body).unwrap(),d);assert_eq!(cursor.as_ref().unwrap().compared_bytes(),0);close(&mut cursor,&mut bank,&model);drop(cursor);close_input(map);
}
